Livro livro1 = new Livro();
livro1.Titulo = "O Cálice Contaminado";
livro1.Autor = "Robert Jackson Bennett";
livro1.Paginas = 448;
livro1.Genero = "Fantasia/Ficção Científica LGBTQ+";
livro1.Sinopse = "Em uma opulenta mansão de Daretana, um oficial imperial de alto escalão morre de repente após uma planta enorme florescer de seu corpo. Completamente fora do comum, todos os indícios do caso apontam para um assassinato, até então sem pista alguma. Agora, a população local corre um grande risco ― mesmo ali, às margens do império, onde existem preocupações maiores por causa dos temíveis leviatãs que invadem as terras de tempos em tempos.\r\n\r\nSó uma detetive de carreira respeitável poderia resolver o caso. Entram em cena Ana Dolabra, de mente afiada e atitudes excêntricas, capaz de solucionar os crimes mais diversos sem nem mesmo sair de casa, e seu novo assistente Dinios Kol, dono de uma habilidade de memorização muito conveniente para uma investigação. No entanto, ambos guardam os próprios enigmas à medida que desvendam uma rede que põe em xeque o próprio Império, caso a misteriosa planta não seja contida.";
livro1.Traducao = true;

