Livro livro4 = new Livro();
livro4.Titulo = "Foundryside";
livro4.Autor = "Robert Jackson Bennett";
livro4.Paginas = 656;
livro4.Genero = "Fantasia Urbana";
livro4.Sinopse = "Em uma cidade movida por magia industrializada, quais são as consequências de interferir na própria realidade?\r\nSancia Grado é uma ladra, e é excelente no que faz. Assim, seu alvo mais recente, um armazém superprotegido no cais de Tevanne, não é nada que suas habilidades únicas não possam resolver.\r\nPorém, sem saber, Sancia foi enviada para roubar um artefato que tem um poder inimaginável, um objeto que poderia revolucionar a tecnologia mágica conhecida como “inscrição”. As casas comerciais que controlam tal magia – a arte de usar comandos codificados para dar vida a objetos cotidianos – já a utilizaram para transformar a cidade de Tevanne em uma enorme e impiedosa máquina capitalista, mas agora buscam liberar os segredos do artefato para atingir objetivos ainda maiores.\r\nCom a sua cabeça à prêmio e uma revolução em curso, Sancia terá de dominar o poder do artefato e se unir aos mais improváveis aliados, se quiser sobreviver. Será ela capaz de arcar com a própria transformação para impedir uma guerra secreta que poderá reescrever a própria realidade?";
livro4.Traducao = true;

Livro livro5 = new Livro();
livro5.Titulo = "Shorefall: a noite do caos";
livro5.Autor = "Robert Jackson Bennett";
livro5.Paginas = 639;
livro5.Genero = "Fantasia Urbana";
livro5.Sinopse = "Na continuação de Foundryside, retorne à cidade de Tevanne, um lugar envolto em uma revolução mágica e onde um mal ancestral ameaça ressurgir\r\nAlguns anos atrás, Sancia Grado ficaria feliz em ver Tevanne queimar. Agora, ela espera transformar sua cidade em algo novo. Algo melhor. Juntamente com os aliados Orso, Gregor e Berenice, ela está prestes a desferir um golpe mortal contra os cruéis governantes de Tevanne e arrancar o poder de suas mãos pela primeira vez em décadas.\r\nMas então vem um aviso aterrorizante: o próprio Crasedes Magnus, o primeiro dos lendários hierofantes, está prestes a renascer. E, se ele retornar, Tevanne será apenas o primeiro lugar a sentir sua ira.\r\nMilhares de anos atrás, Crasedes era um homem comum que fazia o impossível: usando a magia da inscrição — a arte de atribuir senciência a objetos —, ele convenceu a realidade de que era mais do que um mero humano. Empunhando poderes além da compreensão, ele caminhou pelo mundo como um deus por séculos, fazendo sua própria justiça e expurgando o mundo através do fogo e da destruição — até mesmo derrotando a própria morte.\r\nGoste ou não, caberá a Sancia impedi-lo. Mas, para ter uma chance na batalha que está por vir, ela terá que invocar o seu próprio deus — e abrir a porta para uma tecnologia de inscrição que pode mudar o que significa ser humano. Não importa quem vença, nada será como antes…";
livro5.Traducao = true;

Livro livro6 = new Livro();
livro6.Titulo = "Locklands: os abismos esquecidos";
livro6.Autor = "Robert Jackson Bennett";
livro6.Paginas = 723;
livro6.Genero = "Fantasia Urbana";
livro6.Sinopse = "NESTA CONCLUSÃO ELETRIZANTE E EXTRAORDINÁRIA, SANCIA GRADO E COMPANHEIROS PARTICIPAM DE UMA GUERRA DE DEUSES CUJO PEÃO É A PRÓPRIA HUMANIDADE. No terce iro volume da consagrada trilogia Os Fundadores, o grupo desta vez confronta uma entidade cuja inteligência está espalhada pelo mundo: um fantasma na máquina que usa a tecnologia mágica da inscrição para possuir e controlar não apenas objetos, mas mentes humanas. Para tentar combatê-la, precisam usar a inscrição para transformar a si mesmos e seus aliados em um exército — uma sociedade — diferente de tudo que a humanidade já viu. Mesmo assim, o inimigo avança. Implacável. Inabalável. Enquanto o oponente aproxima-se de seu verdadeiro prêmio — uma antiga porta que leva às câmaras no centro da criação —, Sancia e aliados vislumbram uma última oportunidade de detê-lo. Para isso, precisam desvendar as origens misteriosas e seculares das inscrições e realizar o roubo mais ousado que já arriscaram. Mas seu rival pode ter um espião do lado deles — e um último truque na manga. Para ter uma chance de vitória, Sancia, Clave e Berenice precisarão fazer um sacrifício maior do que qualquer outro já feito antes.";
livro6.Traducao = true;

